INSERT INTO materials (course_slug, title, content, video_url, module_index, order_index) VALUES
('ai-untuk-pemula', 'Apa itu Artificial Intelligence?', '<h2>Apa itu Artificial Intelligence (AI)?</h2><p>Artificial Intelligence (AI) adalah teknologi yang memungkinkan mesin melakukan tugas yang biasanya membutuhkan kecerdasan manusia, seperti:</p><ul><li>Mengenali gambar dan suara</li><li>Membuat keputusan berdasarkan data</li><li>Belajar dari pengalaman (machine learning)</li><li>Memahami dan menghasilkan bahasa manusia (LLM)</li></ul><h3>Jenis AI</h3><p>AI terbagi menjadi beberapa jenis:</p><ol><li><strong>Narrow AI (Weak AI)</strong> - AI yang dirancang untuk tugas spesifik, misalnya: Siri, Google Maps, recommendation Netflix.</li><li><strong>General AI (Strong AI)</strong> - AI yang memiliki kecerdasan setara manusia (masih dalam riset).</li><li><strong>Large Language Models (LLM)</strong> - AI yang dilatih dengan dataset besar untuk memahami dan menghasilkan teks, misalnya: ChatGPT, Claude, Gemini.</li></ol><h3>Bagaimana LLM Bekerja?</h3><p>LLM bekerja dengan prinsip <strong>prediksi kata berikutnya</strong>. Model dilatih dengan:</p><ul><li>Dataset teks masif (miliaran kata)</li><li>Arsitektur Transformer (attention mechanism)</li><li>Parameter yang mencapai triliunan (misal: GPT-4 ~1.76 triliun parameter)</li></ul><div class="bg-[#FFF3D6] p-4 rounded-lg mt-4"><p class="text-sm"><strong>📌 Fakta:</strong> ChatGPT dilatih dengan data hingga 2023, sedangkan Claude (Anthropic) menggunakan Constitutional AI - metode pelatihan yang memprioritaskan keamanan dan etika.</p></div>', 'https://www.youtube.com/watch?v=EXAMPLE_VIDEO_1', 0, 0),
('ai-untuk-pemula', 'Lab: Mencoba AI Pertama Kamu', '<h2>Lab: Mencoba AI Pertama Kamu</h2><p>Dalam lab ini, kita akan mencoba menggunakan AI (Claude atau ChatGPT) untuk tugas praktis.</p><h3>Langkah 1: Buat Akun AI</h3><ol><li>Kunjungi <a href="https://claude.ai" target="_blank">Claude.ai</a> atau <a href="https://chat.openai.com" target="_blank">ChatGPT</a></li><li>Buat akun gratis (gunakan email yang aktif)</li><li>Verifikasi akun melalui email</li></ol><h3>Langkah 2: Prompt Pertama</h3><p>Cobalah prompt berikut:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Jelaskan apa itu Machine Learning dalam bahasa Indonesia yang sederhana, seolah-olah kamu menjelaskan kepada adik kelas 5 SD. Gunakan analogi yang mudah dipahami."</div><h3>Langkah 3: Eksperimen dengan Variasi Prompt</h3><p>Cobalah variasi prompt berikut dan bandingkan hasilnya:</p><ul><li>"Jelaskan Machine Learning untuk audiens teknis (programer)"</li><li>"Jelaskan Machine Learning untuk audiens bisnis (manager)"</li><li>"Buatkan ringkasan 3 poin penting tentang Machine Learning"</li></ul><h3>Output yang Diharapkan</h3><p>Setelah menyelesaikan lab ini, kamu harus memiliki:</p><ul><li>Akun AI yang aktif</li><li>Memahami perbedaan respon berdasarkan gaya prompt</li><li>Menyadari bahwa AI merespon berdasarkan konteks yang diberikan</li></ul><div class="bg-[#E8F5E9] p-4 rounded-lg mt-4"><p class="text-sm"><strong>✅ Checklist:</strong></p><ul class="text-sm mt-2"><li>☐ Sudah buat akun AI</li><li>☐ Sudah coba minimal 3 variasi prompt</li><li>☐ Sudah paham perbedaan respon</li></ul></div>', NULL, 0, 1);
INSERT INTO materials (course_slug, title, content, video_url, module_index, order_index) VALUES
('ai-untuk-pemula', 'Dasar Prompt Engineering', '<h2>Dasar Prompt Engineering</h2><p>Prompt engineering adalah seni dan ilmu dalam merancang input (prompt) yang optimal agar AI memberikan output yang diinginkan.</p><h3>Komponen Prompt yang Baik</h3><ol><li><strong>Context (Konteks)</strong> - Latar belakang informasi yang diperlukan AI</li><li><strong>Instruction (Instruksi)</strong> - Perintah yang jelas dan spesifik</li><li><strong>Input Data</strong> - Data atau teks yang ingin diproses</li><li><strong>Output Format</strong> - Format hasil yang diharapkan (JSON, tabel, list, dll)</li><li><strong>Constraint (Batasan)</strong> - Pembatas atau hal yang harus dihindari</li></ol><h3>Contoh Prompt yang Baik vs Buruk</h3><table class="w-full border-collapse border border-[#F0E8D8] mt-4"><thead><tr class="bg-[#F0E8D8]"><th class="border border-[#F0E8D8] p-2 text-left">Buruk</th><th class="border border-[#F0E8D8] p-2 text-left">Baik</th></tr></thead><tbody><tr><td class="border border-[#F0E8D8] p-2">"Jelaskan AI"</td><td class="border border-[#F0E8D8] p-2">"Jelaskan apa itu AI dalam 3 paragraf. Gunakan bahasa Indonesia yang casual profesional. Sertakan 2 contoh aplikasi AI di Indonesia."</td></tr><tr><td class="border border-[#F0E8D8] p-2">"Buat kode Python"</td><td class="border border-[#F0E8D8] p-2">"Buatkan kode Python untuk menghitung luas segitiga. Input: alas dan tinggi. Output: cetak luas. Tambahkan komentar penjelas tiap baris kode."</td></tr></tbody></table><h3>Teknik Prompt Engineering</h3><ul><li><strong>Zero-shot Prompting</strong> - Langsung meminta output tanpa contoh</li><li><strong>Few-shot Prompting</strong> - Memberikan beberapa contoh (examples) sebelum meminta output</li><li><strong>Chain-of-Thought</strong> - Meminta AI untuk berpikir step-by-step (reasoning)</li><li><strong>Role Prompting</strong> - Memberikan peran tertentu pada AI ("Act as a...")</li></ul>', 'https://www.youtube.com/watch?v=EXAMPLE_VIDEO_2', 1, 0),
('ai-untuk-pemula', 'Advanced Prompt Engineering', '<h2>Advanced Prompt Engineering</h2><p>Teknik lanjut untuk mendapatkan output AI yang lebih presisi dan sesuai kebutuhan kompleks.</p><h3>1. Chain-of-Thought (CoT) Prompting</h3><p>Meminta AI untuk memecah masalah menjadi langkah-langkah logis.</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm mt-2">"Saya ingin menghitung ROI dari investasi Rp 10.000.000 yang memberikan return Rp 12.500.000 setelah 2 tahun. Tolong hitung step-by-step: (1) Berapa keuntungan bersih, (2) Berapa ROI persentase per tahun."</div><h3>2. Self-Consistency</h3><p>Meminta AI untuk memberikan beberapa solusi lalu pilih yang terbaik.</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm mt-2">"Berikan 3 strategi marketing untuk produk baru. Lalu, analisis kelebihan dan kekurangan masing-masing, dan rekomendasikan mana yang terbaik untuk startup dengan budget terbatas."</div><h3>3. Tree of Thoughts (ToT)</h3><p>Meminta AI untuk mengeksplorasi beberapa jalur pemikiran sebelum memutuskan.</p><h3>4. Prompt Chaining</h3><p>Memecah tugas kompleks menjadi beberapa prompt berurutan.</p><ol><li>Prompt 1: Ekstrak data penting dari teks</li><li>Prompt 2: Analisis data yang diekstrak</li><li>Prompt 3: Buat rekomendasi berdasarkan analisis</li></ol><div class="bg-[#E3F2FD] p-4 rounded-lg mt-4"><p class="text-sm"><strong>💡 Tips:</strong> Untuk tugas kompleks, jangan satu prompt panjang. Gunakan chain of prompts yang spesifik per langkah.</p></div>', NULL, 1, 1),
('ai-untuk-pemula', 'Lab: Eksperimen Prompt Engineering', '<h2>Lab: Eksperimen Prompt Engineering</h2><p>Praktik langsung dengan berbagai teknik prompt engineering.</p><h3>Tugas 1: Role Prompting</h3><p>Cobalah prompt berikut:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Act as a senior software engineer dengan 10 tahun pengalaman. Jelaskan perbedaan REST API dan GraphQL dalam bahasa Indonesia. Gunakan analogi sederhana. Berikan kapan harus pakai masing-masing."</div><h3>Tugas 2: Few-Shot Prompting</h3><p>Berikan contoh sebelum meminta klasifikasi:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Berikut adalah contoh sentimen: Teks: ''Produk ini luar biasa!'' -> Sentimen: Positif Teks: ''Kualitas buruk, jangan beli.'' -> Sentimen: Negatif Teks: ''Cukup bagus lah.'' -> Sentimen: Netral Sekarang klasifikasi: ''Pelayanan cepat tapi produknya biasa saja.''"</div><h3>Tugas 3: Chain-of-Thought</h3><p>Selesaikan masalah matematika dengan step-by-step:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Sebuah toko memberikan diskon 20% untuk semua barang. Jika harga asli adalah Rp 150.000, berapa harga setelah diskon? Lalu, jika ada pajak 10%, berapa total yang harus dibayar? Tolong hitung step-by-step."</div><h3>Output yang Diharapkan</h3><p>Upload screenshot hasil eksperimen kamu (minimal 3 prompt berbeda) ke komentar atau simpan di portfolio pribadi.</p>', NULL, 1, 2);
INSERT INTO materials (course_slug, title, content, video_url, module_index, order_index) VALUES
('ai-untuk-pemula', 'AI untuk Produktivitas Harian', '<h2>AI untuk Produktivitas Harian</h2><p>Belajar menggunakan AI untuk menghemat waktu dan meningkatkan kualitas kerja harian.</p><h3>1. AI untuk Penulisan (Writing)</h3><ul><li><strong>Draft email</strong> - "Buat draft email follow-up ke klien yang belum bayar invoice 30 hari lebih."</li><li><strong>Proofreading</strong> - "Cek dan perbaiki tata bahasa dari teks berikut: [paste teks]"</li><li><strong>Summarization</strong> - "Buat ringkasan eksekutif 3 poin dari laporan berikut: [paste laporan]"</li><li><strong>Translation</strong> - "Translate teks berikut ke bahasa Inggris yang naturral (bukan literal): [teks]"</li></ul><h3>2. AI untuk Analisis Data</h3><ul><li>"Analisis data penjualan berikut: [data]. Berikan 3 insight utama."</li><li>"Buat visualisasi data (dalam teks/ASCII) dari data berikut: [data]"</li><li>"Identifikasi tren dari data penjualan 12 bulan terakhir ini: [data]"</li></ul><h3>3. AI untuk Meeting & Dokumentasi</h3><ul><li>"Buat agenda meeting untuk proyek peluncuran produk, durasi 1 jam, 5 peserta."</li><li>"Ringkas notulensi meeting berikut menjadi 5 action items: [notulensi]"</li><li>"Buat follow-up email setelah meeting dengan poin-poin yang didiskusikan."</li></ul><h3>4. AI untuk Riset</h3><ul><li>"Cari 5 tren teknologi 2026 di bidang IT dan jelaskan dampaknya bagi karir programmer."</li><li>"Bandingkan 3 tools project management (Asana, Trello, Monday) untuk tim 10 orang."</li></ul><div class="bg-[#FFF3D6] p-4 rounded-lg mt-4"><p class="text-sm"><strong>⏱ Waktu yang Dihemat:</strong> Rata-rata karyawan menghemat 2-3 jam per hari dengan menggunakan AI untuk tugas rutin.</p></div>', 'https://www.youtube.com/watch?v=EXAMPLE_VIDEO_3', 2, 0),
('ai-untuk-pemula', 'AI untuk Profesional: Use Cases Nyata', '<h2>AI untuk Profesional: Use Cases Nyata</h2><p>Implementasi AI di berbagai peran profesional.</p><h3>Untuk Programer</h3><ul><li><strong>Code Review</strong>: "Review kode JavaScript berikut, cari potensi bug dan optimasi: [kode]"</li><li><strong>Debugging</strong>: "Kenapa kode ini error? [error message]. Perbaiki kodenya."</li><li><strong>Documentation</strong>: "Buatkan JSDoc documentation untuk fungsi berikut: [kode]"</li><li><strong>Refactoring</strong>: "Refactor kode berikut agar lebih clean dan maintainable: [kode]"</li></ul><h3>Untuk Marketing</h3><ul><li><strong>Copywriting</strong>: "Buat 5 variasi headline untuk iklan produk skincare, target audiens wanita 25-35 tahun."</li><li><strong>Content Calendar</strong>: "Buat content calendar Instagram 30 hari untuk brand kopi lokal."</li><li><strong>SEO</strong>: "Optimasi artikel berikut untuk keyword ''belajar AI'': [artikel]"</li></ul><h3>Untuk HR</h3><ul><li><strong>Job Description</strong>: "Buat JD untuk posisi Senior Frontend Developer di startup fintech."</li><li><strong>Screening</strong>: "Review CV berikut dan berikan skor 1-10 untuk posisi Data Analyst: [CV]"</li><li><strong>Interview Questions</strong>: "Buat 10 pertanyaan interview behavioral untuk posisi Project Manager."</li></ul><h3>Untuk Freelancer</h3><ul><li><strong>Proposal</strong>: "Buat proposal proyek web development untuk klien UMKM, budget Rp 15jt."</li><li><strong>Time Tracking</strong>: "Buat sistem penjadwalan proyek 3 bulan dengan 5 milestone."</li><li><strong>Invoice</strong>: "Buat template invoice profesional untuk jasa desain grafis."</li></ul>', NULL, 2, 1),
('ai-untuk-pemula', 'Lab: Produktivitas dengan AI', '<h2>Lab: Produktivitas dengan AI</h2><p>Praktik langsung menggunakan AI untuk tugas profesional nyata.</p><h3>Tugas 1: Email Profesional</h3><p>Buatlah draft email berikut menggunakan AI:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Buat draft email kepada atasan (Manager). Isi: (1) Melaporkan progress proyek sudah 80%, (2) Ada kendala di API integration yang butuh 3 hari tambahan, (3) Minta persetujuan untuk extend deadline 5 hari. Gunakan nada yang profesional tapi tidak kaku."</div><h3>Tugas 2: Analisis Data Sederhana</h3><p>Gunakan AI untuk menganalisis data penjualan berikut:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">Data: Jan: 10jt, Feb: 12jt, Mar: 9jt, Apr: 15jt, Mei: 18jt, Jun: 14jt "Dari data tersebut: (1) Bulan apa yang penjualan tertinggi? (2) Hitung rata-rata penjualan per bulan. (3) Berikan prediksi untuk bulan Juli. (4) Identifikasi tren yang terjadi."</div><h3>Tugas 3: Portofolio Project</h3><p>Buat deskripsi proyek untuk portofolio:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Buat deskripsi proyek untuk portofolio website e-commerce. Teknologi: Next.js, Supabase, Tailwind. Fitur: auth, cart, checkout Midtrans. Tampilkan 3 bullet point pencapaian (gunakan metric angka)."</div><h3>Output</h3><p>Simpan hasil dari ketiga tugas tersebut dalam satu dokumen (PDF atau Google Doc) sebagai bukti penyelesaian lab.</p>', NULL, 2, 2);
INSERT INTO materials (course_slug, title, content, video_url, module_index, order_index) VALUES
('ai-untuk-pemula', 'AI untuk Transformasi Bisnis', '<h2>AI untuk Transformasi Bisnis</h2><p>Bagaimana AI dapat digunakan untuk mentransformasi operasional dan strategi bisnis.</p><h3>1. Customer Service Otomatis</h3><ul><li>Chatbot AI untuk 24/7 customer support</li><li>Analisis sentimen customer review</li><li>Auto-responder untuk FAQ</li><li>Escalation ke humans ketika AI tidak bisa handle</li></ul><h3>2. Personalisasi Produk & Layanan</h3><ul><li>Rekomendasi produk berdasarkan riwayat belanja</li><li>Dynamic pricing berdasarkan demand</li><li>Personalized email marketing</li><li>Predictive analytics untuk inventory</li></ul><h3>3. Content Creation Masal</h3><ul><li>Generate product descriptions (1000+ produk dalam hitungan menit)</li><li>Social media content calendar otomatis</li><li>SEO-optimized blog posts</li><li>Ad copy variasi A/B testing</li></ul><h3>4. Strategic Decision Making</h3><ul><li>Market research otomatis</li><li>Competitor analysis</li><li>Financial forecasting</li><li>Risk assessment</li></ul><div class="bg-[#E8F5E9] p-4 rounded-lg mt-4"><p class="text-sm"><strong>📈 Studi Kasus:</strong> Starbucks menggunakan AI untuk personalisasi rekomendasi minuman, menghasilkan kenaikan penjualan 3% di Q1 2024.</p></div>', 'https://www.youtube.com/watch?v=EXAMPLE_VIDEO_4', 3, 0),
('ai-untuk-pemula', 'AI untuk Pengembangan Karier', '<h2>AI untuk Pengembangan Karier</h2><p>Bagaimana AI dapat mempercepat pertumbuhan karir Anda.</p><h3>1. Skill Gap Analysis</h3><p>Gunakan AI untuk mengidentifikasi kekurangan skill:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Saya seorang frontend developer dengan skill: React, JavaScript, CSS. Target posisi: Senior Fullstack Developer. Analisis skill gap yang harus saya pelajari dan buatkan learning path 6 bulan."</div><h3>2. Interview Preparation</h3><ul><li>"Simulasikan interview untuk posisi Data Scientist. Ajukan 10 pertanyaan teknis dan behavioral."</li><li>"Berikan feedback untuk jawaban interview berikut: [jawaban]"</li><li>"Buat 5 pertanyaan cerdas yang bisa saya tanyakan kepada interviewer."</li></ul><h3>3. Resume & Portofolio Optimization</h3><ul><li>"Optimasi CV saya untuk posisi Product Manager: [paste CV]"</li><li>"Buat professional summary 3 kalimat yang menonjolkan pencapaian:"</li><li>"Review portofolio website saya dan berikan 5 saran perbaikan: [URL]"</li></ul><h3>4. Networking & Personal Branding</h3><ul><li>"Buat 5 ide konten LinkedIn yang bisa viral untuk target audiens IT profesional."</li><li>"Tulis artikel LinkedIn 500 kata tentang tren AI di industri:"</li><li>"Buat personal branding statement untuk saya: [background]"</li></ul><h3>5. Salary Negotiation</h3><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Saya mendapat tawaran gaji Rp 15.000.000 untuk posisi Senior Developer. Rata-rata pasar Rp 18.000.000 - Rp 22.000.000. Tolong bantu saya negosiasi dengan script percakapan yang profesional."</div>', NULL, 3, 1),
('ai-untuk-pemula', 'Lab: AI untuk Karier', '<h2>Lab: AI untuk Karier</h2><p>Project praktis untuk memajukan karir menggunakan AI.</p><h3>Project: Career Pivot Planning</h3><p>Misalkan Anda ingin berpindah karier dari profesi saat ini ke IT (spesifik: AI Engineer).</p><h3>Langkah 1: Skill Gap Analysis</h3><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Saya seorang [isi profesi saat ini] dengan skill: [sebutkan 3-5 skill]. Saya ingin beralih ke AI Engineer. Apa skill yang harus saya pelajari? Buatkan roadmap 12 bulan lengkap dengan sumber belajar gratis dan berbayar."</div><h3>Langkah 2: Resume Optimization</h3><p>Buat ulang CV yang dioptimasi untuk transisi karier:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Optimasi CV berikut untuk posisi Junior AI Engineer. Highlight skill yang relevan, tambahkan proyek portofolio, dan buat professional summary yang kuat: [paste CV lama]"</div><h3>Langkah 3: Interview Simulation</h3><p>Simulasikan interview teknis:</p><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Act as a hiring manager di tech company. Simulasikan interview untuk posisi Junior AI Engineer. Ajukan 5 pertanyaan teknis dan berikan feedback untuk jawaban saya."</div><h3>Output Akhir</h3><p>Kumpulkan dalam satu PDF:</p><ol><li>Career roadmap 12 bulan</li><li>CV yang dioptimasi</li><li>Hasil simulasi interview dengan feedback</li><li>(Bonus) 3 ide konten LinkedIn untuk personal branding</li></ol>', NULL, 3, 2);
INSERT INTO materials (course_slug, title, content, video_url, module_index, order_index) VALUES
('ai-untuk-pemula', 'Popular AI Tools 2026', '<h2>Popular AI Tools 2026</h2><p>Kenali dan gunakan AI tools yang paling populer dan berdampak di 2026.</p><h3>1. LLM Chatbots</h3><table class="w-full border-collapse border border-[#F0E8D8] mt-2"><thead><tr class="bg-[#F0E8D8]"><th class="border border-[#F0E8D8] p-2">Tool</th><th class="border border-[#F0E8D8] p-2">Kelebihan</th><th class="border border-[#F0E8D8] p-2">Best For</th></tr></thead><tbody><tr><td class="border border-[#F0E8D8] p-2">ChatGPT (OpenAI)</td><td class="border border-[#F0E8D8] p-2">Plugins, browsing, DALL-E</td><td class="border border-[#F0E8D8] p-2">General purpose, creative writing</td></tr><tr><td class="border border-[#F0E8D8] p-2">Claude (Anthropic)</td><td class="border border-[#F0E8D8] p-2">Long context (200k tokens), safety</td><td class="border border-[#F0E8D8] p-2">Code review, document analysis</td></tr><tr><td class="border border-[#F0E8D8] p-2">Gemini (Google)</td><td class="border border-[#F0E8D8] p-2">Integration Google Workspace</td><td class="border border-[#F0E8D8] p-2">Google ecosystem users</td></tr></tbody></table><h3>2. AI untuk Coding</h3><ul><li><strong>GitHub Copilot</strong> - Autocomplete code dalam IDE</li><li><strong>Cursor</strong> - AI-first code editor (fork dari VS Code)</li><li><strong>Replit Agent</strong> - Full-stack development dengan AI</li><li><strong>v0.dev</strong> - Generate UI components dari prompt</li></ul><h3>3. AI untuk Design</h3><ul><li><strong>Midjourney</strong> - Image generation berkualitas tinggi</li><li><strong>Canva Magic Studio</strong> - AI design untuk non-designer</li><li><strong>Figma AI</strong> - UI/UX design assistant</li><li><strong>Sora (OpenAI)</strong> - Text-to-video generation</li></ul><h3>4. AI untuk Productivity</h3><ul><li><strong>Notion AI</strong> - AI dalam workspace & note-taking</li><li><strong>Slack AI</strong> - Search & summarize Slack threads</li><li><strong>Zoom AI Companion</strong> - Meeting summary otomatis</li><li><strong>Microsoft 365 Copilot</strong> - AI di seluruh suite Microsoft</li></ul><div class="bg-[#FFF3D6] p-4 rounded-lg mt-4"><p class="text-sm"><strong>💰 Tips Biaya:</strong> Banyak tools memiliki versi gratis (limited) yang cukup untuk pemula. Upgrade ke Pro hanya jika sudah menghasilkan ROI (misal: menghemat 10+ jam/minggu).</p></div>', 'https://www.youtube.com/watch?v=EXAMPLE_VIDEO_5', 4, 0),
('ai-untuk-pemula', 'Building AI Workflow: Dari Nol ke Produktif', '<h2>Building AI Workflow: Dari Nol ke Produktif</h2><p>Belajar membangun workflow end-to-end dengan mengintegrasikan berbagai AI tools.</p><h3>Workflow 1: Content Creation Pipeline</h3><ol><li><strong>Riset</strong>: ChatGPT/Claude - "Cari 10 topik tren tentang [niche] di 2026"</li><li><strong>Outline</strong>: Claude - "Buat outline artikel SEO untuk keyword [keyword]"</li><li><strong>Draft</strong>: ChatGPT - "Expand outline menjadi artikel 1500 kata"</li><li><strong>Edit</strong>: Grammarly GO + Human review</li><li><strong>Visual</strong>: Midjourney - "Generate featured image untuk artikel [topic]"</li><li><strong>SEO</strong>: Semrush AI - Optimasi on-page</li><li><strong>Publish</strong>: WordPress + AI Social Media poster</li></ol><h3>Workflow 2: Software Development Lifecycle</h3><ol><li><strong>Requirements</strong>: Claude - "Analisis kebutuhan aplikasi [deskripsi]"</li><li><strong>Architecture</strong>: ChatGPT - "Buat system design untuk aplikasi [name]"</li><li><strong>Coding</strong>: Cursor/GitHub Copilot - Generate kode</li><li><strong>Testing</strong>: Claude - "Buat unit test untuk kode berikut: [kode]"</li><li><strong>Review</strong>: CodeRabbit (AI code review)</li><li><strong>Deploy</strong>: Vercel AI - Otomatis deployment</li></ol><h3>Workflow 3: Data Analysis</h3><ol><li><strong>Import</strong>: Claude - "Analisis struktur dataset CSV berikut"</li><li><strong>Cleaning</strong>: ChatGPT - "Tulis Python script untuk cleaning data: [requirements]"</li><li><strong>Analysis</strong>: Claude - "Cari insight dari data berikut: [data]"</li><li><strong>Visualization</strong>: ChatGPT - "Buat kode Python matplotlib untuk visualisasi: [chart type]"</li><li><strong>Report</strong>: Claude - "Buat laporan PDF eksekutif dari analisis berikut"</li></ol><h3>Tips Integrasi Workflow</h3><ul><li>Gunakan Zapier/Make untuk koneksi antar tools (automation)</li><li>Simpan prompt templates di Notion untuk reuse</li><li>Buat SOP yang mendokumentasikan kapan menggunakan tool mana</li><li>Review output AI secara berkala untuk menjaga kualitas</li></ul>', NULL, 4, 1),
('ai-untuk-pemula', 'Final Project: Build Your AI-Powered Portfolio', '<h2>Final Project: Build Your AI-Powered Portfolio</h2><p>Project akhir yang mengintegrasikan semua yang telah dipelajari.</p><h3>Objektif</h3><p>Membuat portofolio online yang menonjolkan kemampuan menggunakan AI secara praktis.</p><h3>Requirement</h3><ol><li><strong>Personal Branding</strong>: Gunakan AI untuk membuat tagline, bio, dan professional summary</li><li><strong>Project Showcase</strong>: Minimal 3 proyek yang dikerjakan dengan bantuan AI (tunjukkan prompt + hasil)</li><li><strong>Blog Section</strong>: 2 artikel yang ditulis dengan bantuan AI (tunjukkan proces editing manual)</li><li><strong>Testimonial</strong>: Generate testimoni dummy dengan AI, lalu validasi dengan klien nyata</li><li><strong>Contact Form</strong>: Integrasi dengan AI chatbot untuk auto-respon</li></ol><h3>Langkah-Langkah</h3><h4>1. Planning (Gunakan Claude/ChatGPT)</h4><div class="bg-[#F0E8D8] p-4 rounded-lg font-mono text-sm">"Saya ingin membuat portofolio sebagai [role: misal Data Analyst]. Tolong buatkan: (1) Site map, (2) Color palette, (3) Typography recommendation, (4) 5 ide fitur unik yang membedakan saya dari kompetitor."</div><h4>2. Content Generation</h4><p>Gunakan AI untuk generate semua teks content (dengan human editing):</p><ul><li>Hero section headline + subheadline</li><li>About Me section (professional story)</li><li>Project descriptions (gunakan STAR method)</li><li>Blog posts (tulis draft manual, gunakan AI untuk editing)</li></ul><h4>3. Development</h4><p>Gunakan AI coding tools:</p><ul><li>Cursor/GitHub Copilot untuk generate komponen UI</li><li>ChatGPT untuk troubleshooting bugs</li><li>Claude untuk code review</li></ul><h4>4. Deployment</h4><p>Gunakan platform dengan AI integration:</p><ul><li>Vercel (AI-optimized deployment)</li><li>Netlify (AI form handling)</li><li>GitHub Pages + Jekyll (AI-generated static site)</li></ul><h3>Deliverables</h3><ol><li>URL live portofolio</li><li>PDF report (3-5 halaman) yang menjelaskan: (a) Bagaimana AI digunakan, (b) Prompt yang digunakan, (c) % kontribusi AI vs manual, (d) Lesson learned</li><li>Code repository (jika portofolio dibuat sendiri)</li></ol><div class="bg-[#E8F5E9] p-4 rounded-lg mt-4"><p class="text-sm"><strong>🎉 Selamat!</strong> Setelah menyelesaikan final project ini, Anda sudah siap menggunakan AI secara profesional untuk mempercepat karir. Sertifikat akan diterbitkan otomatis setelah semua module selesai.</p></div>', NULL, 4, 2);
